package webapp
import("io";"net/http/httptest";"strings";"testing";"tialloystudio/internal/app")
func TestWorkbenchServesInteractiveUI(t *testing.T){h:=New(app.NewState());w:=httptest.NewRecorder();h.ServeHTTP(w,httptest.NewRequest("GET","/",nil));if w.Code!=200{t.Fatal(w.Code)};b,_:=io.ReadAll(w.Result().Body);s:=string(b);for _,needle:=range []string{"Ti Alloy Studio","Crystal / Alloy","SQS","Defects / Surface","α/β Interface","EOS","GSFE","structureCanvas","analysisCanvas","validationPanel"}{if !strings.Contains(s,needle){t.Fatalf("missing %q",needle)}}}
func TestWorkbenchUsesRepeatableBlobDownloadsAndInteractiveValues(t *testing.T){h:=New(app.NewState());w:=httptest.NewRecorder();h.ServeHTTP(w,httptest.NewRequest("GET","/app.js",nil));if w.Code!=200{t.Fatal(w.Code)};b,_:=io.ReadAll(w.Result().Body);s:=string(b);if strings.Contains(s,"location.href=`/api/export"){t.Fatal("export still navigates the application away")};for _,needle:=range []string{"URL.createObjectURL","chartTooltip","atomTooltip"}{if !strings.Contains(s,needle){t.Fatalf("missing %q",needle)}}}
